"use client";

import { useActionState } from "react";
import { refundOrder, updateOrder } from "@/app/admin/actions";

const STATUSES = ["PAID", "PROCESSING", "SHIPPED", "DELIVERED", "CANCELLED"] as const;

export function OrderStatusForm({ id, status, courier, trackingNumber }: { id: string; status: string; courier: string; trackingNumber: string }) {
  const [state, action, pending] = useActionState(updateOrder, undefined);
  return (
    <form action={action} className="space-y-3">
      <input type="hidden" name="id" value={id} />
      <div>
        <label className="label" htmlFor="status">Status</label>
        <select id="status" name="status" defaultValue={STATUSES.includes(status as never) ? status : "PAID"} className="input">
          {STATUSES.map((s) => <option key={s} value={s}>{s.charAt(0) + s.slice(1).toLowerCase()}</option>)}
        </select>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div><label className="label" htmlFor="courier">Courier</label><input id="courier" name="courier" defaultValue={courier} className="input" placeholder="DTDC / Own delivery" /></div>
        <div><label className="label" htmlFor="trackingNumber">Tracking no.</label><input id="trackingNumber" name="trackingNumber" defaultValue={trackingNumber} className="input" /></div>
      </div>
      <div><label className="label" htmlFor="note">Internal note</label><input id="note" name="note" className="input" maxLength={500} /></div>
      {state?.error && <p className="text-sm text-danger">{state.error}</p>}
      {state?.ok && <p className="text-sm text-success">Order updated.</p>}
      <button disabled={pending} className="btn-dark w-full">{pending ? "Saving…" : "Update order"}</button>
    </form>
  );
}

export function RefundForm({ id, total }: { id: string; total: number }) {
  const [state, action, pending] = useActionState(refundOrder, undefined);
  return (
    <form action={action} onSubmit={(e) => { if (!confirm("Issue this refund through Razorpay? This cannot be undone.")) e.preventDefault(); }} className="space-y-2">
      <input type="hidden" name="id" value={id} />
      <label className="label" htmlFor="amount">Refund amount (₹) — blank for full refund</label>
      <input id="amount" name="amount" type="number" step="0.01" min="1" max={total / 100} className="input" placeholder={String(total / 100)} />
      {state?.error && <p className="text-sm text-danger">{state.error}</p>}
      {state?.ok && <p className="text-sm text-success">Refund initiated. Razorpay will notify when processed.</p>}
      <button disabled={pending} className="btn-outline w-full text-danger">{pending ? "Processing…" : "Refund via Razorpay"}</button>
    </form>
  );
}
